// === Tab: mySketch ===
// Made for the #WCCChallenge - topic "Obscure";
// The idea is that the background (which i arguably could've worked more on...) is obscured by black nothing, but windows form and move allowing us to see through.
// The approach is, uh, rather novel for me? I kinda came up with it in the shower. There are many triangles, slowly spinning and drifting over the screen,
// and the windows form when 3 or more triangles overlap simultaneously (this is done with a GLSL shader for performance).
// Artistically this is very underbaked, but code-wise it was a nice learning experience for me.
// Might run slowly for some depending on PC (but I hope it doesn't)

let triangleCount = 40;
let triangleSize = 200;
let triangleSpeed = 1.4;
let triangleRotation = 0.01;

let triangles = [];

let gr;
let gr2;
let gr_bg;
let canv;
let fShader;
let fShader2;

function init_bg(){
	gr_bg.background(0);
	gr_bg.noStroke();

	let circs = [];
	for(let i=0; i<1000; i++){
		let x = random(800);
		let y = random(800);
		let r = 8+random(30);
		circs.push([x,y,r]);
	}
	for(let circ of circs){
		var x = circ[0];
		var y = circ[1];
		var r = circ[2];

		let cf = x/800;
		gr_bg.fill(230*(1-cf) + 80*cf, 40*(1-cf) + 150*cf, 80*(1-cf) + 90*cf);
		if(random()<0.01)gr_bg.fill(40, 70, 170);

		gr_bg.ellipse(x, y, r,r);
	}
	for(let circ of circs){
		var x = circ[0];
		var y = circ[1];
		var r = circ[2];

		var cf = x/800;
		gr_bg.fill(0);

		gr_bg.ellipse(x, y, r/2,r/2);
	}
}

function setup() {
	for(let i=0; i<triangleCount; i++){
		triangles.push(new Triangle());
	}

	gr = createGraphics(800,800,P2D);
	gr2 = createGraphics(800,800,WEBGL);
	gr_bg = createGraphics(800,800,P2D);

	canv = createCanvas(800, 800, WEBGL);
	background(0);

	fShader = createFilterShader(shaderCode);
	fShader2 = gr2.createFilterShader(shaderCode2);

	init_bg();
}

function render(){
	background(0);
	for(let tri of triangles){
		tri.render();
	}

	filter(fShader);
	gr.image(canv, 0, 0);
	gr.filter(BLUR, 5);
	image(gr, -400, -400);
	gr2.image(canv,-400,-400);
	gr2.filter(fShader2);

	image(gr_bg, -400, -400);
	image(gr2, -400, -400);
}

function draw() {
	render();
	for(let tri of triangles){
		tri.update();
	}
}

// === Tab: tab2 ===
class Triangle{
	constructor(){
		this.x = random(800+triangleSize*2)-triangleSize;
		this.y = random(800+triangleSize*2)-triangleSize;
		this.vertices = [];
		this.initVertices();
		let tempVec = createVector((1+random()*0.2)*triangleSpeed, 0).rotate(random()*TAU);
		this.vx = tempVec.x;
		this.vy = tempVec.y;
		this.theta = random()*TAU;
		this.omega = (random(2)-1)*triangleRotation;
	}

	initVertices(){
		for(let i=0; i<3; i++){
			var tempVec = createVector((random(0.6)+0.4)*triangleSize, 0).rotate(i/3 * TAU);
			this.vertices.push([tempVec.x, tempVec.y]);
		}
	}

	render(){
		push();
		noStroke();
		blendMode(ADD);
		fill(255,255,255,1);
		translate(this.x-400, this.y-400);
		rotate(this.theta);
		triangle(...this.vertices[0], ...this.vertices[1], ...this.vertices[2]);
		pop();
	}

	update(){
		this.x += this.vx;
		this.y += this.vy;
		this.theta += this.omega;

		if(this.x < -triangleSize)this.x += 800 + triangleSize*2;
		if(this.x > 800+triangleSize)this.x -= 800 + triangleSize*2;
		if(this.y < -triangleSize)this.y += 800 + triangleSize*2;
		if(this.y > 800+triangleSize)this.y -= 800 + triangleSize*2;
	}
}

// === Tab: tab3 ===
// this is my first time writing glsl...
let shaderCode = `
precision highp float;

varying vec2 vTexCoord;
uniform sampler2D tex0;

void main() {
  vec4 color = texture2D(tex0, vTexCoord);

  int sth = int(color.r*255.);
	float res = sth>=3? 1.:0.;
  gl_FragColor = vec4(res,res,res, 1.0);
}
`;

let shaderCode2 = `
precision highp float;

varying vec2 vTexCoord;
uniform sampler2D tex0;

void main() {
  vec4 color = texture2D(tex0, vTexCoord);

  float res = color.r > 0.015 ? 1. : color.r/0.015;

	float alpha = color.r < 0.2 ? 1. : (color.r > 0.4 ? 0. : (0.4-color.r)/0.2);
	res *= alpha * 0.96;
	res = 0.06 + 0.94*res;
  gl_FragColor = vec4(res,res,res, alpha);
}
`;

